raw:
{
  "spells": [
    {
      "id": "spell_fire_07",
      "theory": "余烬刻印把魔力压进非活体材料的表层，顺着刻痕留下暗红火纹。木料、陶片、石面都能承载，但潮湿或油污表面会使纹路偏移。印记不发热，只发出微弱红光，可被辨认却不会灼伤触摸者。刻印的清晰度取决于材料纹理是否均匀，纹路越粗糙，字迹越容易模糊。",
      "casting": "以指节或钝器在材料上划出连续凹槽，沿槽底匀速注入魔力，最后一笔需回勾收尾。刻写时手腕应保持稳定，避免中途停顿。",
      "failure": "魔力注入过快时，刻痕边缘会焦黑卷曲，火纹断续如碎星，无法组成完整签记。材料内部若含水汽，表面会泛起白雾，刻印在数息内褪为焦痕，并留下刺鼻烟味。",
      "counters": [
        "用湿泥或厚灰覆盖刻痕，可遮断红光并模糊纹路。",
        "以细砂磨去材料表层，刻印会随凹槽消失而失效。"
      ],
      "socialConsequences": "河谷乡约常请人用余烬刻印在界石或木牌上标记承诺，因它难以篡改且夜间可见。中陆公会却担忧伪造签记，要求刻印者先登记纹样。琥珀海岸的货主用其标记货箱，但港务规定不得在他人货品上私刻，违者按损毁货物追究。陶工和木匠欢迎这种标记，而抄写员抱怨它抢走了部分契约誊写生意。",
      "law": {
        "river": "consent",
        "city": "permit",
        "port": "permit"
      },
      "proficiencyEffects": [
        "初学时纹路粗细不匀，红光只能持续很短时间。",
        "较熟练者能让刻印在干燥木料上保持整夜清晰。",
        "熟练者可控制刻痕深浅，使印记在石面上不易磨灭。",
        "极高熟练度下纹路细密如画，但仍只限非活体材料。"
      ]
    },
    {
      "id": "spell_fire_08",
      "theory": "焰矢术将魔力聚成一道短促火束，沿视线方向喷射。火束依赖空气中的尘粒维持形态，因此受潮或强风会缩短射程。它不会追踪目标，掩体、盾面或厚布都能阻断。火焰接触目标后迅速消散，仅留下焦痕与灼痛，不会持续燃烧。",
      "casting": "双指并拢指向目标，在呼气时释放魔力，同时手腕向前一送。若目标移动，需在释放前重新对准，不可中途改变方向。",
      "failure": "魔力输出不稳时，火束会在指尖炸开成火星，灼伤施术者手掌。若空气湿重，火束飞出数步便散为青烟，目标只感到一阵热风。瞄准偏差时火焰擦过掩体边缘，在墙面留下焦黑痕迹，暴露施术位置。",
      "counters": [
        "举盾或厚木板挡住视线，火束便无法绕过掩体。",
        "泼洒湿沙或水雾可打散火束中的尘粒，使其提前熄灭。"
      ],
      "socialConsequences": "河谷猎户在驱赶野兽时偶尔使用，但乡约要求事后向被惊扰的邻家说明。中陆城市中，公会许可的护卫可在巡逻时施放，平民私自朝人发射则按纵火伤人论处。琥珀海岸的船主严禁在甲板或货舱附近使用，因帆布与绳索极易被火星引燃，违者港务会追究航运事故责任。铁匠与皮匠常抱怨焰矢术烧坏他们的成品，而佣兵则视其为可靠的远程手段。",
      "law": {
        "river": "consent",
        "city": "permit",
        "port": "crime"
      },
      "proficiencyEffects": [
        "初学时常因呼气过早而射偏，火束仅能飞短短几步。",
        "较熟练者可在十步内准确击中静止目标，火星不再反溅。",
        "熟练者能压低火束角度，使其擦过掩体上方命中后方目标。",
        "极高熟练度下火束收束紧密，但射程与威力仍限于给定范围。"
      ]
    },
    {
      "id": "spell_fire_09",
      "theory": "釉火调律把魔力导入窑炉内壁，使热量沿陶坯轮廓均匀铺开。它不增减火焰总量，只调整热流方向，减少局部过热点。魔力通过窑壁的耐火泥层传导，因此炉壁越厚，调律越缓慢。施术期间需持续维持纹路，一旦中断，热量会回涌至原先的集中处。",
      "casting": "以树脂在窑口内壁画一圈螺旋纹，双掌贴壁缓慢送入魔力，同时用脚轻踏地面稳定节奏。升温阶段需每数息检查一次纹路是否完整。",
      "failure": "纹路断裂时，窑内热流会突然偏向一侧，陶坯受热不均而开裂，发出清脆的崩裂声。魔力反冲会使窑壁发红，施术者手掌感到灼烫，需立即停手并等待窑温自然回落。",
      "counters": [
        "撤走窑口树脂纹样，魔力便失去引导路径而散逸。",
        "向窑内投入湿柴制造浓烟，可扰乱热流方向使调律失效。"
      ],
      "socialConsequences": "河谷陶村依赖釉火调律烧制祭器与储粮罐，乡约规定窑主须与调律师口头约定分成。中陆公会要求调律师持许可执业，因失败会连带损毁整窑陶坯，引发赔偿纠纷。琥珀海岸的砖窑与瓦窑也请人调律，但港务规定窑场不得靠近货栈，以免火星随风飘入航运货堆。陶工行会欢迎减少裂损，而柴商担心均匀升温会降低柴耗，影响他们的销路。",
      "law": {
        "river": "consent",
        "city": "permit",
        "port": "permit"
      },
      "proficiencyEffects": [
        "初学时螺旋纹容易画歪，窑内温差反而比不调律更大。",
        "较熟练者能维持一窑陶坯不裂，但仍需频繁查看火色。",
        "熟练者可针对不同器形调整热流，厚胎薄胎同窑少损。",
        "极高熟练度下整窑温差极小，但升温时间仍受柴火限制。"
      ]
    }
  ]
}
